.dashboard-home {
  --dashboard-bg: #e7eff5;
  --dashboard-border: rgba(82, 103, 122, 0.22);
  --dashboard-card: rgba(255, 255, 255, 0.86);
  --dashboard-shadow: 0 12px 28px rgba(47, 61, 76, 0.12);
  --dashboard-accent: #2f6fed;
  --dashboard-accent-soft: rgba(47, 111, 237, 0.1);
  --dashboard-green: #2d8a63;
  --dashboard-amber: #b56a18;
  --dashboard-purple: #6f2cff;
  --dashboard-purple-soft: rgba(111, 44, 255, 0.22);
  --dashboard-text: #203040;
  --dashboard-muted: #617181;
  --dashboard-node-radius: 8px;
  --dashboard-control-radius: 6px;
  --dashboard-shared-row-height: clamp(268px, 21.8vw, 344px);
  --dashboard-shared-gap: 10px;
  --dashboard-shared-margin-bottom: 16px;
  --dashboard-front-stack-gap: 16px;
  --dashboard-shared-padding: 9px 11px;
  --dashboard-planning-gap: 10px;
  --dashboard-planning-margin-bottom: 16px;
  --dashboard-planning-section-min-height: 164px;
  --dashboard-planning-panel-padding: 10px;
  --dashboard-planning-header-min-height: 36px;
  --dashboard-planning-header-margin-bottom: 8px;
  --dashboard-planning-heading-icon-size: 30px;
  --dashboard-planning-control-height: 31px;
  --dashboard-planning-control-padding: 4px 11px;
  --dashboard-planning-period-gap: 8px;
  --dashboard-planning-period-padding: 9px 10px;
  --dashboard-planning-period-header-min-height: 41px;
  --dashboard-planning-period-header-margin-bottom: 9px;
  --dashboard-planning-period-icon-size: 39px;
  --dashboard-planning-period-reset-size: 39px;
  --dashboard-planning-list-height: 278px;
  --dashboard-planning-item-height: 58px;
  --dashboard-planning-item-padding: 5px;
  --dashboard-progress-card-padding: 9px 10px;
  --dashboard-progress-item-padding: 7px 8px 6px;
  --dashboard-progress-item-icon-size: 42px;
  /* 固定底部工具栏不参与文档流；真实滚动留白由末尾 spacer 提供。 */
  --dashboard-scroll-toolbar-clearance: 88px;
  padding: 24px;
  scroll-padding-bottom: calc(24px + var(--dashboard-scroll-toolbar-clearance));
  background: var(--dashboard-bg);
  min-height: 100%;
  color: var(--dashboard-text);
  position: relative;
  /* 禁止 Chromium 把主页末尾占位或动态任务节点选作滚动锚点。
     否则首次重命名、删除、新建等 DOM 高度变化会自动改写 scrollTop。 */
  overflow-anchor: none;
}

.dashboard-home.dashboard-home--density-compact {
  --dashboard-shared-row-height: clamp(248px, 20.1vw, 316px);
  --dashboard-shared-padding: 8px 10px;
  --dashboard-planning-section-min-height: 152px;
  --dashboard-planning-panel-padding: 9px;
  --dashboard-planning-header-min-height: 34px;
  --dashboard-planning-header-margin-bottom: 7px;
  --dashboard-planning-heading-icon-size: 28px;
  --dashboard-planning-control-height: 29px;
  --dashboard-planning-control-padding: 4px 10px;
  --dashboard-planning-period-gap: 7px;
  --dashboard-planning-period-padding: 8px 9px;
  --dashboard-planning-period-header-min-height: 38px;
  --dashboard-planning-period-header-margin-bottom: 8px;
  --dashboard-planning-period-icon-size: 36px;
  --dashboard-planning-period-reset-size: 36px;
  --dashboard-planning-list-height: 252px;
  --dashboard-planning-item-height: 54px;
  --dashboard-progress-card-padding: 8px 9px;
  --dashboard-progress-item-padding: 6px 7px;
  --dashboard-progress-item-icon-size: 39px;
}

.dashboard-home.dashboard-home--density-relaxed {
  --dashboard-shared-row-height: clamp(300px, 24vw, 380px);
  --dashboard-shared-padding: 10px 12px;
  --dashboard-planning-section-min-height: 176px;
  --dashboard-planning-panel-padding: 12px;
  --dashboard-planning-header-min-height: 38px;
  --dashboard-planning-header-margin-bottom: 9px;
  --dashboard-planning-heading-icon-size: 32px;
  --dashboard-planning-control-height: 32px;
  --dashboard-planning-control-padding: 5px 13px;
  --dashboard-planning-period-gap: 9px;
  --dashboard-planning-period-padding: 10px 11px;
  --dashboard-planning-period-header-min-height: 45px;
  --dashboard-planning-period-header-margin-bottom: 10px;
  --dashboard-planning-period-icon-size: 42px;
  --dashboard-planning-period-reset-size: 42px;
  --dashboard-planning-list-height: 306px;
  --dashboard-planning-item-height: 63px;
  --dashboard-planning-item-padding: 6px;
  --dashboard-progress-card-padding: 10px 11px;
  --dashboard-progress-item-padding: 8px 9px 7px;
  --dashboard-progress-item-icon-size: 44px;
}

/* BEGIN Banner Shared Block: hero shell, motto cloud, and control chrome */
.dashboard-home__hero {
  --dashboard-hero-shell-radius: 12px;
  box-sizing: border-box;
  display: flex;
  justify-content: space-between;
  gap: 24px;
  align-items: flex-start;
  margin-bottom: 20px;
  padding: 20px;
  border-style: solid;
  border-width: 1px 1px 0.5px;
  border-color: transparent;
  border-radius: var(--dashboard-hero-shell-radius) !important;
  background-color: #f1f6fc !important;
  background-image: none !important;
  box-shadow: none !important;
  overflow: hidden !important;
  clip-path: inset(0 round var(--dashboard-hero-shell-radius));
  background-clip: padding-box;
  position: relative;
  aspect-ratio: 3 / 1;
  min-height: 180px;
  isolation: isolate;
}

.dashboard-home__hero::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 0;
  border-radius: inherit;
  pointer-events: none;
  background: linear-gradient(160deg, rgba(250, 252, 255, 0.98), rgba(233, 241, 253, 0.94));
}

.dashboard-home__hero::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 1;
  border-style: solid;
  border-width: 1px 1px 0.5px;
  border-color: rgba(195, 212, 235, 0.24);
  border-radius: inherit;
  box-shadow:
    inset 0 0 0 2px rgba(255, 255, 255, 0.76),
    0 -1px 0 0 rgba(167, 194, 226, 0.24);
  pointer-events: none;
}

.dashboard-home__hero--height-1 {
  aspect-ratio: 9 / 2;
  min-height: 120px;
}

.dashboard-home__hero--height-2 {
  aspect-ratio: 27 / 4;
  min-height: 80px;
}

.dashboard-home__hero--height-3 {
  aspect-ratio: 81 / 8;
  min-height: 54px;
}

.dashboard-home__hero--custom-height {
  aspect-ratio: var(--dashboard-hero-custom-ratio, 3);
  min-height: calc(180px * var(--dashboard-hero-custom-scale, 1));
}

.dashboard-home__hero.has-banner {
  color: #fff;
}

.dashboard-home__hero.has-banner::before {
  background:
    linear-gradient(
      90deg,
      rgba(8, 18, 30, var(--dashboard-hero-overlay-opacity, 0.58)),
      rgba(8, 18, 30, calc(var(--dashboard-hero-overlay-opacity, 0.58) * 0.3448)) 58%,
      rgba(8, 18, 30, calc(var(--dashboard-hero-overlay-opacity, 0.58) * 0.5862))
    ),
    var(--dashboard-hero-image);
  background-size: cover;
  background-position: center var(--dashboard-hero-image-position-y, 50%);
}

.dashboard-home__hero.has-banner::after {
  border-color: rgba(214, 228, 246, 0.42);
}

.dashboard-home__hero-copy,
.dashboard-home__hero-actions {
  position: relative;
  z-index: 2;
}

.dashboard-home__hero-copy {
  padding: 0;
  border-radius: 8px;
  contain: layout style;
}

.dashboard-home__hero.has-banner .dashboard-home__hero-copy {
  background: transparent;
  box-shadow: none;
  backdrop-filter: none;
}

.dashboard-home__hero.has-banner .dashboard-home__eyebrow,
.dashboard-home__hero.has-banner .dashboard-home__subtitle {
  color: rgba(255, 255, 255, 0.9);
  text-shadow: none;
}

.dashboard-home__hero.has-banner .dashboard-home__title {
  color: #fff;
  text-shadow: none;
}

.dashboard-home__hero-credit {
  position: absolute;
  top: 10px;
  left: 10px;
  z-index: 3;
  max-width: calc(100% - 340px);
  margin: 0;
  padding: 4px 0 0;
  color: var(--dashboard-muted);
  font-size: 13px;
  line-height: 1.2;
  white-space: nowrap;
  opacity: 0;
  pointer-events: none;
  transition: opacity 120ms ease 0ms;
  contain: layout style;
}

.dashboard-home__hero.has-banner .dashboard-home__hero-credit {
  color: rgba(255, 255, 255, 0.92);
}

.dashboard-home__hero-credit-link {
  appearance: none;
  color: inherit !important;
  font-weight: 700;
  text-decoration: underline;
  text-underline-offset: 2px;
}

.dashboard-home__hero.is-controls-revealed .dashboard-home__hero-credit {
  opacity: 1;
  pointer-events: auto;
  transition-delay: 0ms;
}

.dashboard-home__motto-cloud {
  position: absolute;
  inset: 0;
  z-index: 1;
  pointer-events: none;
  overflow: hidden;
  contain: layout style;
}

.dashboard-home__motto-cloud.is-centered {
  display: grid;
  place-items: center;
  padding: clamp(24px, 5vw, 56px) clamp(48px, 8vw, 120px);
}

.dashboard-home__motto-item {
  position: absolute;
  min-width: min(620px, 42%);
  min-height: 0;
  max-width: min(720px, 58%);
  color: rgba(255, 255, 255, 0.72);
  font-weight: 800;
  line-height: 1.15;
  text-shadow: none;
  white-space: normal;
  transform: none;
}

.dashboard-home__motto-item.is-centered {
  position: static;
  min-width: 0;
  max-width: min(980px, 78%);
  color: rgba(255, 255, 255, 0.9);
  font-size: clamp(1.8rem, 2.7vw, 3.2rem);
  font-weight: 900;
  line-height: 1.22;
  text-align: center;
  text-shadow: none;
}

.dashboard-home__hero.is-motto-text-dark .dashboard-home__motto-item {
  color: rgba(31, 42, 52, 0.78);
}

.dashboard-home__hero.is-motto-text-dark .dashboard-home__motto-item.is-centered {
  color: rgba(24, 34, 43, 0.92);
}

.dashboard-home__hero.is-motto-text-dark .dashboard-home__hero-credit,
.dashboard-home__hero.is-motto-text-dark .dashboard-home__hero-control-meta {
  color: rgba(24, 34, 43, 0.92);
}

.dashboard-home__hero.is-motto-text-island .dashboard-home__motto-item,
.dashboard-home__hero.is-motto-text-island .dashboard-home__hero-credit,
.dashboard-home__hero.is-motto-text-island .dashboard-home__hero-control-meta {
  color: rgba(77, 150, 98, 0.88);
}

.dashboard-home__hero.is-motto-text-island .dashboard-home__motto-item.is-centered {
  color: #4d9662;
}

.dashboard-home__hero-controls {
  --dashboard-hero-control-size: 30px;
  --dashboard-hero-control-gap: 6px;
  --dashboard-hero-control-meta-width: 96px;
  position: absolute;
  top: 10px;
  right: 10px;
  bottom: 10px;
  z-index: 85;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  align-items: flex-end;
  gap: 8px;
  padding: 0;
  border: 1px solid transparent;
  border-radius: var(--dashboard-node-radius);
  background: transparent;
  box-shadow: none;
  width: max-content;
  max-width: calc(100% - 20px);
  overflow: visible;
  opacity: 0;
  pointer-events: none;
  transition: opacity 120ms ease 0ms;
  contain: layout style;
}

.dashboard-home__hero-actions {
  display: grid;
  grid-template-columns: max-content;
  align-items: start;
  justify-items: stretch;
  gap: 6px;
  justify-content: flex-start;
  position: relative;
  z-index: 80;
  align-self: flex-end;
  width: max-content;
  max-height: 100%;
  contain: layout style;
}

.dashboard-home__hero-actions-row {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  gap: var(--dashboard-hero-control-gap);
  width: 100%;
  max-width: 100%;
  margin-left: auto;
  padding: 0;
  border: 1px solid transparent;
  border-radius: var(--dashboard-node-radius);
  background: transparent;
  box-shadow: none;
  contain: layout style;
}

.dashboard-home__hero.is-controls-revealed .dashboard-home__hero-controls {
  opacity: 1;
  pointer-events: auto;
  transition-delay: 0ms;
}

.dashboard-home__motto-module {
  position: relative;
  width: 40px;
  min-width: 40px;
  height: 40px;
  min-height: 40px;
  max-height: 100%;
  border: 1px solid rgba(82, 103, 122, 0.22);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.86);
  box-shadow: 0 12px 28px rgba(32, 48, 64, 0.16);
  overflow: visible;
}

.dashboard-home__motto-module[open] {
  width: 40px;
  min-width: 40px;
  height: 40px;
}

.dashboard-home__motto-module:not([open]) {
  width: 40px;
  min-width: 40px;
  height: 40px;
}

.dashboard-home__motto-module:not([open]) .dashboard-home__square-action-label {
  display: none;
}

.dashboard-home__motto-module-summary {
  box-sizing: border-box;
  list-style: none;
  width: 40px;
  min-width: 40px;
  height: 40px;
  min-height: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 2px;
  padding: 3px;
  cursor: pointer;
  color: var(--dashboard-text);
}

.dashboard-home__motto-module-summary::-webkit-details-marker {
  display: none;
}

.dashboard-home__motto-module-body {
  position: fixed;
  width: min(420px, 62vw);
  max-height: min(520px, 70vh);
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-height: 0;
  overflow: auto;
  padding: 10px;
  border: 1px solid rgba(120, 144, 156, 0.18);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.94);
  box-shadow: 0 18px 36px rgba(32, 48, 64, 0.18);
  z-index: 10000;
}

.dashboard-home__hero-height-buttons {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  gap: var(--dashboard-hero-control-gap);
  width: 100%;
  min-width: 0;
  contain: layout style;
}

.dashboard-home__hero-height-controls {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 0;
  margin-left: 0;
  width: max-content;
  min-width: 0;
  flex: 0 0 auto;
  contain: layout style;
}

.dashboard-home__hero-top-section-buttons {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  gap: var(--dashboard-hero-control-gap);
  width: 100%;
  min-width: 0;
  contain: layout style;
}

.dashboard-home__hero-control-buttons {
  display: grid;
  grid-auto-flow: column;
  grid-auto-columns: var(--dashboard-hero-control-size);
  grid-template-columns: none;
  grid-auto-rows: var(--dashboard-hero-control-size);
  align-items: center;
  justify-content: end;
  gap: var(--dashboard-hero-control-gap);
  width: max-content;
  max-width: none;
  flex: 0 0 auto;
  white-space: nowrap;
  margin-left: 0;
  contain: layout style;
}

.dashboard-home__hero-control-buttons--6 {
  grid-template-columns: repeat(6, var(--dashboard-hero-control-size));
  grid-auto-rows: var(--dashboard-hero-control-size);
}

.dashboard-home__hero-control-buttons--7 {
  grid-template-columns: repeat(7, var(--dashboard-hero-control-size));
  grid-auto-rows: var(--dashboard-hero-control-size);
}

.dashboard-home__hero-control-buttons--8 {
  grid-template-columns: repeat(8, var(--dashboard-hero-control-size));
  grid-auto-rows: var(--dashboard-hero-control-size);
}

.dashboard-home__hero-control-buttons--9 {
  grid-template-columns: repeat(9, var(--dashboard-hero-control-size));
  grid-auto-rows: var(--dashboard-hero-control-size);
}

.dashboard-home__hero-control-buttons--11 {
  grid-template-columns: repeat(11, var(--dashboard-hero-control-size));
  grid-auto-rows: var(--dashboard-hero-control-size);
}

.dashboard-home__hero-control-buttons--12 {
  grid-template-columns: repeat(12, var(--dashboard-hero-control-size));
  grid-auto-rows: var(--dashboard-hero-control-size);
}

.dashboard-home__hero-control-meta {
  display: inline-flex;
  align-items: center;
  justify-content: flex-start;
  gap: 6px;
  flex: 0 0 auto;
  width: var(--dashboard-hero-control-meta-width);
  min-width: var(--dashboard-hero-control-meta-width);
  white-space: nowrap;
  color: rgba(248, 251, 255, 0.92);
  text-shadow: none;
}

.dashboard-home__hero-control-label {
  font-size: 12px;
  font-weight: 700;
  line-height: 1;
  text-align: left;
}

.dashboard-home__hero-control-divider {
  font-size: 12px;
  line-height: 1;
  opacity: 0.72;
}

.dashboard-home__hero-height-button {
  font-size: 14px;
  line-height: 1;
}

.dashboard-home__hero-height-button--preset {
  font-family: "Segoe UI Emoji", "Apple Color Emoji", "Noto Color Emoji", sans-serif;
  font-variant-emoji: emoji;
  font-size: 15px;
}

.dashboard-home__hero-refresh-button {
  font-size: 14px;
  line-height: 1;
}

.dashboard-home__hero-top-section-button {
  font-size: 14px;
  line-height: 1;
}

.dashboard-home__hero-height-button--custom {
  font-size: 13px;
  font-weight: 800;
  letter-spacing: 0.02em;
}

.dashboard-home__hero-button-placeholder {
  width: var(--dashboard-hero-control-size);
  min-width: var(--dashboard-hero-control-size);
  height: var(--dashboard-hero-control-size);
  border: 1px solid transparent;
  border-radius: 7px;
  visibility: hidden;
  pointer-events: none;
}

.dashboard-home__hero-height-slider {
  width: 100%;
  padding: 0 10px;
  border: 0 solid rgba(255, 255, 255, 0.24);
  border-radius: 10px;
  background: rgba(18, 28, 42, 0.28);
  box-shadow: none;
  opacity: 0;
  max-height: 0;
  overflow: hidden;
  pointer-events: none;
  transform: translateY(-4px);
  transition: opacity 120ms ease, transform 120ms ease;
  contain: layout paint style;
}

.dashboard-home__hero-height-slider.is-active {
  margin-top: 6px;
  padding: 8px 10px 9px;
  border-width: 1px;
  box-shadow:
    inset 0 0 0 1px rgba(255, 255, 255, 0.08),
    0 8px 16px rgba(10, 18, 28, 0.16);
  opacity: 1;
  max-height: 84px;
  pointer-events: auto;
  transform: translateY(0);
}

.dashboard-home__hero-height-slider-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  width: 100%;
  margin-bottom: 8px;
  color: rgba(247, 251, 255, 0.94);
  text-shadow: none;
}

.dashboard-home__hero-height-slider-label,
.dashboard-home__hero-height-slider-value {
  font-size: 11px;
  font-weight: 700;
  line-height: 1;
}

.dashboard-home__hero-height-slider-input {
  width: 100%;
  min-width: 0;
  display: block;
  margin: 0;
  accent-color: rgba(255, 255, 255, 0.92);
}

/* BEGIN Shared Modules Shared Block: banner-hosted hero control rows */
.dashboard-home__hero-module-switches {
  position: relative;
  z-index: 80;
  display: flex;
  flex: 0 0 auto;
  flex-wrap: nowrap;
  gap: var(--dashboard-hero-control-gap);
  align-items: center;
  align-content: flex-end;
  justify-content: end;
  width: max-content;
  margin-left: auto;
  contain: layout style;
}

.dashboard-home__hero-module-separator {
  position: relative;
  width: var(--dashboard-hero-control-size);
  min-width: var(--dashboard-hero-control-size);
  height: var(--dashboard-hero-control-size);
  pointer-events: none;
}

.dashboard-home__hero-module-separator::before {
  content: "";
  position: absolute;
  top: 6px;
  bottom: 6px;
  left: 50%;
  width: 1px;
  transform: translateX(-50%);
  border-radius: 999px;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.76), rgba(167, 194, 226, 0.42));
  opacity: 0.96;
}

.dashboard-home__toolbar-separator {
  width: 2px;
  min-width: 2px;
  height: 24px;
  margin: 0 5px;
  pointer-events: none;
  flex: 0 0 2px;
  box-sizing: border-box;
  align-self: center;
  border-radius: 999px;
  background: rgba(34, 46, 64, 0.72);
  opacity: 1;
}

.dashboard-home__toolbar-separator::before {
  content: none;
}

.dashboard-home__hero-module-switch-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--dashboard-hero-control-gap);
  width: 100%;
  min-width: 0;
  padding: 0;
  border: 1px solid transparent;
  border-radius: var(--dashboard-node-radius);
  background: transparent;
  box-shadow: none;
  contain: layout style;
}

.dashboard-home__hero-module-switch {
  position: relative;
  display: grid;
  place-items: center;
  box-sizing: border-box;
  width: 30px;
  min-width: 30px;
  height: 30px;
  padding: 0;
  border-style: solid;
  border-width: 1px 1px 0.5px;
  border-color: rgba(195, 212, 235, 0.32);
  border-radius: 7px;
  background: linear-gradient(180deg, rgba(255, 250, 247, 0.8), rgba(252, 239, 230, 0.76));
  box-shadow:
    inset 0 0 0 2px rgba(255, 255, 255, 0.76),
    0 -1px 0 0 rgba(167, 194, 226, 0.28);
  cursor: pointer;
  filter: none;
  opacity: 0.6;
  contain: layout paint style;
}

.dashboard-home__hero-module-switch[draggable="true"] {
  cursor: grab;
}

