/* BEGIN Banner Shared Block: separator normalization overrides */
.dashboard-home__hero-module-separator,
.dashboard-home__toolbar-separator,
.dashboard-home__excalidraw-toolbar-separator,
.dashboard-home__grid.is-focus-lower-section :is(.dashboard-home__toolbar-separator, .dashboard-home__excalidraw-toolbar-separator) {
  position: relative !important;
  box-sizing: border-box !important;
  pointer-events: none !important;
  padding: 0 !important;
  border: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
  opacity: 1 !important;
  transform: none !important;
  align-self: center !important;
}

.dashboard-home__hero-module-separator {
  width: var(--dashboard-hero-control-size) !important;
  min-width: var(--dashboard-hero-control-size) !important;
  max-width: var(--dashboard-hero-control-size) !important;
  height: var(--dashboard-hero-control-size) !important;
  min-height: var(--dashboard-hero-control-size) !important;
  max-height: var(--dashboard-hero-control-size) !important;
  flex: 0 0 var(--dashboard-hero-control-size) !important;
  margin: 0 !important;
}

.dashboard-home__toolbar-separator,
.dashboard-home__excalidraw-toolbar-separator,
.dashboard-home__grid.is-focus-lower-section :is(.dashboard-home__toolbar-separator, .dashboard-home__excalidraw-toolbar-separator) {
  width: 0 !important;
  min-width: 0 !important;
  max-width: 0 !important;
  height: 28px !important;
  min-height: 28px !important;
  max-height: 28px !important;
  flex: 0 0 0 !important;
  margin: 0 10px !important;
  border-left: 1px solid rgba(34, 46, 64, 0.72) !important;
