.dashboard-home__hero-module-separator::after,
.dashboard-home__toolbar-separator::after,
.dashboard-home__excalidraw-toolbar-separator::after,
.dashboard-home__grid.is-focus-lower-section :is(.dashboard-home__toolbar-separator, .dashboard-home__excalidraw-toolbar-separator)::after {
