/* BEGIN Shared Modules Shared Block: shell grid, popup, planning row, and final shell overrides */
.dashboard-home__shared-modules {
  display: grid !important;
  grid-template-columns: repeat(21, minmax(0, 1fr));
  grid-auto-rows: var(--dashboard-shared-row-height);
  align-items: stretch;
  column-gap: var(--dashboard-shared-gap) !important;
  row-gap: var(--dashboard-shared-gap) !important;
  margin: 0 0 var(--dashboard-front-stack-gap) !important;
  contain: layout style;
}

/* Bind the six-module row height directly to the selected density state. */
.dashboard-home.dashboard-home--density-compact .dashboard-home__shared-modules {
  grid-auto-rows: clamp(248px, 20.1vw, 316px) !important;
}

.dashboard-home.dashboard-home--density-standard .dashboard-home__shared-modules {
  grid-auto-rows: clamp(268px, 21.8vw, 344px) !important;
}

.dashboard-home.dashboard-home--density-relaxed .dashboard-home__shared-modules {
  grid-auto-rows: clamp(300px, 24vw, 380px) !important;
}

.dashboard-home__shared-modules.is-section-hidden {
  display: none !important;
}

/* Mobile: keep each of the six home modules at a readable full-card width.
   The module strip scrolls horizontally instead of compressing all cards into one viewport. */
@media (max-width: 760px) {
  .dashboard-home .dashboard-home__shared-modules {
    grid-template-columns: none !important;
    grid-template-rows: var(--dashboard-shared-row-height) !important;
    grid-auto-flow: column;
    grid-auto-columns: minmax(288px, min(420px, calc(100vw - 48px)));
    grid-auto-rows: unset !important;
    align-items: stretch;
    max-width: 100%;
    padding: 0 2px 8px;
    overflow-x: auto;
    overflow-y: hidden;
    overscroll-behavior-x: contain;
    scroll-snap-type: x proximity;
    scrollbar-gutter: stable;
    touch-action: pan-x pan-y;
  }

  .dashboard-home .dashboard-home__shared-modules > .dashboard-home__shared-module {
    grid-column: auto !important;
    grid-row: 1;
    width: 100%;
    min-width: 0;
    scroll-snap-align: start;
    scroll-snap-stop: normal;
  }

  .dashboard-home.dashboard-home--density-compact .dashboard-home__shared-modules {
    grid-template-rows: clamp(248px, 78vw, 316px) !important;
  }

  .dashboard-home.dashboard-home--density-standard .dashboard-home__shared-modules {
    grid-template-rows: clamp(268px, 84vw, 344px) !important;
  }

  .dashboard-home.dashboard-home--density-relaxed .dashboard-home__shared-modules {
    grid-template-rows: clamp(300px, 92vw, 380px) !important;
  }
}

.dashboard-home__shared-module {
