/* Progress and daily schedule share one responsive planning row. */
.dashboard-home__planning-row {
  --planning-glass-border: rgba(195, 212, 235, 0.24);
  --planning-glass-surface: linear-gradient(180deg, rgba(255, 255, 255, 0.98), rgba(239, 246, 255, 0.94));
  --planning-glass-panel: linear-gradient(180deg, rgba(248, 251, 255, 0.98), rgba(237, 244, 253, 0.94));
  --planning-glass-card: linear-gradient(180deg, rgba(255, 255, 255, 0.97), rgba(244, 249, 255, 0.92));
  --planning-glass-highlight: rgba(255, 255, 255, 0.78);
  --planning-glass-edge: rgba(167, 194, 226, 0.24);
  --planning-glass-shell:
    inset 0 0 0 2px var(--planning-glass-highlight),
    0 -1px 0 0 var(--planning-glass-edge);
  display: grid !important;
  grid-template-columns: repeat(24, minmax(0, 1fr));
  align-items: stretch;
  column-gap: var(--dashboard-planning-gap) !important;
  row-gap: var(--dashboard-planning-gap) !important;
  min-width: 0;
  margin: 0 0 var(--dashboard-front-stack-gap) !important;
  overflow-anchor: none;
}

.dashboard-home__planning-row > .dashboard-home__progress-section {
  grid-column: span 15;
}

.dashboard-home__planning-row > .dashboard-home__schedule-section {
  grid-column: span 9;
}

.dashboard-home__planning-row.is-single-visible > .dashboard-home__progress-section,
.dashboard-home__planning-row.is-single-visible > .dashboard-home__schedule-section {
  grid-column: 1 / -1;
}

.dashboard-home__planning-row.is-row-hidden {
  display: none !important;
}

.dashboard-home__planning-row > .dashboard-home__progress-section,
.dashboard-home__planning-row > .dashboard-home__schedule-section {
  min-width: 0;
  height: auto;
  align-self: stretch;
  margin: 0;
}

@media (max-width: 960px) {
  .dashboard-home__planning-row {
    grid-template-columns: minmax(0, 1fr);
  }

  .dashboard-home__planning-row > .dashboard-home__progress-section,
  .dashboard-home__planning-row > .dashboard-home__schedule-section {
    grid-column: 1 / -1;
  }
}

/* Final shared-module shell: keep every outer card visually identical. */
