/* BEGIN Calendar Shared Block: shell and module styles */
.dashboard-home__shared-module--calendar {
  --dashboard-calendar-panel-radius: 12px;
  --calendar-surface-color: #f1f6fc;
  --calendar-surface-gradient: linear-gradient(160deg, rgba(250, 252, 255, 0.98), rgba(233, 241, 253, 0.94));
  --calendar-panel-color: #f6f9ff;
  --calendar-panel-gradient: linear-gradient(180deg, rgba(255, 255, 255, 0.96), rgba(238, 246, 255, 0.92));
  --calendar-panel-border: rgba(195, 212, 235, 0.24);
  --calendar-panel-shadow: inset 0 0 0 2px rgba(255, 255, 255, 0.76), 0 -1px 0 0 rgba(167, 194, 226, 0.24);
  --calendar-text: #17365d;
  --calendar-solar-text: #122b49;
  --calendar-muted-text: #60728a;
  --calendar-accent-text: #2f7cf1;
  --calendar-today-number-text: #2f7cf1;
  --calendar-date-text: #17365d;
  --calendar-title-text: #17367d;
  --calendar-title-border: rgba(198, 214, 236, 0.58);
  --calendar-weekday-text: #17365d;
  --calendar-weekend-blue: #1765d1;
  --calendar-weekend-red: #df3b2f;
  --calendar-today-text: #ffffff;
  --calendar-divider-bg: linear-gradient(90deg, transparent, rgba(74, 139, 186, 0.42), transparent);
  --calendar-month-button-border: rgba(195, 212, 235, 0.24);
  --calendar-month-button-bg: linear-gradient(180deg, rgba(255, 255, 255, 0.96), rgba(244, 248, 255, 0.9));
  --calendar-month-button-text: #1d3580;
  --calendar-month-button-shadow: inset 0 0 0 2px rgba(255, 255, 255, 0.76), 0 -1px 0 0 rgba(167, 194, 226, 0.24);
  --calendar-month-button-hover-border: rgba(151, 183, 231, 0.62);
  --calendar-month-button-hover-bg: linear-gradient(180deg, rgba(255, 255, 255, 0.98), rgba(236, 244, 255, 0.94));
  --calendar-month-button-hover-text: #22448f;
  --calendar-day-border-width: 1px 1px 0.5px;
  --calendar-day-border: rgba(195, 212, 235, 0.24);
  --calendar-day-bg: linear-gradient(180deg, rgba(255, 255, 255, 0.95), rgba(244, 248, 255, 0.9));
  --calendar-day-shadow: inset 0 0 0 2px rgba(255, 255, 255, 0.76), 0 -1px 0 0 rgba(167, 194, 226, 0.24);
  --calendar-today-day-border: rgba(103, 222, 255, 0.88);
  --calendar-today-day-bg: linear-gradient(180deg, #5dc0ff, #278cf5);
  --calendar-today-day-shadow: inset 0 0 0 2px rgba(255, 255, 255, 0.45), 0 -1px 0 0 rgba(45, 128, 223, 0.34);
  grid-column: span 4;
  container-type: inline-size;
  padding: 0;
  overflow: hidden;
  border-color: rgba(182, 204, 233, 0.34);
  border-radius: var(--dashboard-calendar-panel-radius) !important;
  clip-path: inset(0 round var(--dashboard-calendar-panel-radius));
  background-color: var(--calendar-surface-color) !important;
  background-image: var(--calendar-surface-gradient) !important;
  background-clip: padding-box;
  box-shadow: none !important;
}

.dashboard-home__calendar-host {
  position: absolute;
  inset: min(10px, 2.15cqw) min(8px, 1.72cqw) min(8px, 1.72cqw);
  min-width: 0;
  min-height: 0;
  box-sizing: border-box;
  overflow: hidden;
  border-radius: var(--dashboard-node-radius);
  clip-path: inset(0 round var(--dashboard-node-radius));
  color: var(--calendar-text);
  contain: layout style;
}

.dashboard-home__calendar-shell {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 0.265fr) minmax(0, 0.735fr);
  gap: min(5px, 1.08cqw);
  width: 100%;
  height: 100%;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
  border-radius: var(--dashboard-node-radius);
  clip-path: inset(0 round var(--dashboard-node-radius));
  contain: layout style;
}

.dashboard-home__calendar-today,
.dashboard-home__calendar-month {
  position: relative;
  min-width: 0;
  min-height: 0;
  height: 100%;
  box-sizing: border-box;
  overflow: hidden;
  border-style: solid;
  border-width: 1px 1px 0.5px;
  border-color: var(--calendar-panel-border);
  border-radius: var(--dashboard-calendar-panel-radius) !important;
  clip-path: inset(0 round var(--dashboard-calendar-panel-radius));
  background-color: var(--calendar-panel-color) !important;
  background-image: var(--calendar-panel-gradient) !important;
  background-clip: padding-box;
  box-shadow: var(--calendar-panel-shadow) !important;
  contain: layout style;
}

.dashboard-home__calendar-today {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: min(10px, 2.15cqw);
  padding: min(72px, 15.55cqw) min(14px, 3cqw) min(34px, 7.35cqw);
  text-align: center;
}

.dashboard-home__calendar-today::before {
  content: "";
  position: absolute;
  right: -6%;
  bottom: -10%;
  width: 84%;
  aspect-ratio: 1 / 1;
  border-radius: 50%;
  background:
    linear-gradient(180deg, rgba(132, 184, 255, 0.2), rgba(73, 144, 241, 0.08));
  border: 1px solid rgba(255, 255, 255, 0.58);
  box-shadow:
    inset 0 0 0 1px rgba(207, 225, 249, 0.28),
    -18% 22% 0 -8% rgba(114, 166, 241, 0.16);
  pointer-events: none;
}

.dashboard-home__calendar-today::after {
  position: absolute;
  content: "";
  left: 12%;
  bottom: 13%;
  width: min(8px, 1.72cqw);
  height: min(8px, 1.72cqw);
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.92);
  box-shadow:
    0 0 0 min(6px, 1.3cqw) rgba(255, 255, 255, 0.12),
    min(96px, 20.7cqw) min(28px, 6cqw) 0 0 rgba(255, 255, 255, 0.82);
  opacity: 0.84;
  pointer-events: none;
}

.dashboard-home__calendar-today-seal {
  --dashboard-calendar-today-button-width: min(56px, 12.1cqw);
  --dashboard-calendar-today-button-height: min(34px, 7.35cqw);
  position: absolute;
  top: min(18px, 3.9cqw);
  left: 0;
  right: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  z-index: 2;
  width: var(--dashboard-calendar-today-button-width);
  min-width: var(--dashboard-calendar-today-button-width);
  max-width: var(--dashboard-calendar-today-button-width);
  height: var(--dashboard-calendar-today-button-height);
  min-height: var(--dashboard-calendar-today-button-height);
  max-height: var(--dashboard-calendar-today-button-height);
  margin: 0 auto;
  box-sizing: border-box;
  padding: 0;
  border-style: solid;
  border-width: 1px 1px 0.5px;
  border-color: rgba(134, 201, 255, 0.44);
  border-radius: min(12px, 2.6cqw);
  background: linear-gradient(180deg, #71b9ff, #3a8cf2);
  color: #ffffff !important;
  font-size: min(14px, 3cqw);
  font-weight: 800;
  line-height: 1;
  cursor: pointer;
  outline: none;
  transform: none !important;
  transition: none;
  box-shadow:
    inset 0 0 0 2px rgba(255, 255, 255, 0.38),
    0 -1px 0 0 rgba(64, 145, 232, 0.3) !important;
}

.dashboard-home__calendar-today-seal:hover,
.dashboard-home__calendar-today-seal:focus,
.dashboard-home__calendar-today-seal:focus-visible,
.dashboard-home__calendar-today-seal:active {
  left: 0;
  right: 0;
  width: var(--dashboard-calendar-today-button-width);
  min-width: var(--dashboard-calendar-today-button-width);
  max-width: var(--dashboard-calendar-today-button-width);
  height: var(--dashboard-calendar-today-button-height);
  min-height: var(--dashboard-calendar-today-button-height);
  max-height: var(--dashboard-calendar-today-button-height);
  margin: 0 auto;
  padding: 0;
  border-color: rgba(134, 201, 255, 0.44);
  background: linear-gradient(180deg, #71b9ff, #3a8cf2);
  color: #ffffff !important;
  outline: none;
  transform: none !important;
  box-shadow:
    inset 0 0 0 2px rgba(255, 255, 255, 0.38),
    0 -1px 0 0 rgba(64, 145, 232, 0.3) !important;
}

.dashboard-home__calendar-today-number {
  margin-top: 0;
  color: var(--calendar-today-number-text);
  font-family: Georgia, "Times New Roman", serif;
  font-size: min(156px, 18.4cqw);
  font-weight: 500;
  line-height: 0.9;
  text-shadow: none !important;
}

.dashboard-home__calendar-today-weekday {
  color: var(--calendar-text);
  font-size: min(44px, 5.2cqw);
  font-weight: 800;
  line-height: 1.1;
}

.dashboard-home__calendar-divider {
  width: 68%;
  height: 1px;
  margin: min(8px, 1.72cqw) 0 min(10px, 2.15cqw);
  background: var(--calendar-divider-bg);
}

.dashboard-home__calendar-today-date {
  color: var(--calendar-date-text);
  font-size: min(20px, 2.35cqw);
  font-weight: 700;
  line-height: 1.15;
}

.dashboard-home__calendar-today-lunar {
  color: var(--calendar-accent-text);
  font-size: min(22px, 2.6cqw);
  font-weight: 800;
  line-height: 1.15;
}

.dashboard-home__calendar-month {
  display: grid;
  grid-template-rows: min(46px, 9.9cqw) minmax(0, 1fr);
  align-content: stretch;
  padding: min(8px, 1.72cqw) min(3px, 0.65cqw) min(6px, 1.3cqw);
  gap: min(2px, 0.43cqw);
}

.dashboard-home__calendar-month-title {
  display: grid;
  grid-template-columns: min(34px, 7.35cqw) minmax(0, 1fr) min(34px, 7.35cqw);
  align-items: center;
  gap: min(3px, 0.65cqw);
  min-height: 0;
  padding: 0 0 min(4px, 0.86cqw);
  border-bottom: 1px solid var(--calendar-title-border);
  color: var(--calendar-text);
  text-align: center;
}

.dashboard-home__calendar-month-title strong {
  min-width: 0;
  color: var(--calendar-title-text);
  font-size: min(30px, 3.55cqw);
  font-weight: 800;
  line-height: 1;
  white-space: nowrap;
}

.dashboard-home__calendar-month-button {
  appearance: none;
  outline: none;
  display: grid;
  place-items: center;
  width: min(30px, 6.5cqw);
  height: min(30px, 6.5cqw);
  min-width: 0;
  min-height: 0;
  box-sizing: border-box;
  padding: 0;
  border-style: solid;
  border-width: 1px 1px 0.5px;
  border-color: var(--calendar-month-button-border) !important;
  border-radius: min(12px, 2.6cqw);
  background: var(--calendar-month-button-bg) !important;
  color: var(--calendar-month-button-text) !important;
  box-shadow: var(--calendar-month-button-shadow) !important;
  font-size: min(18px, 2.15cqw);
  font-weight: 800;
  line-height: 1;
  cursor: pointer;
}

.dashboard-home__calendar-month-button:hover,
.dashboard-home__calendar-month-button:focus-visible {
  border-color: var(--calendar-month-button-hover-border) !important;
  background: var(--calendar-month-button-hover-bg) !important;
  color: var(--calendar-month-button-hover-text) !important;
}

.dashboard-home__calendar-grid {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  grid-template-rows: min(33px, 7.1cqw) repeat(var(--dashboard-calendar-weeks, 6), minmax(0, 1fr));
  align-content: stretch;
  width: 100%;
  height: 100%;
  box-sizing: border-box;
  min-height: 0;
  gap: 0;
  contain: layout style;
}

.dashboard-home__calendar-weekday,
.dashboard-home__calendar-day {
  min-width: 0;
  text-align: center;
}

.dashboard-home__calendar-weekday {
  display: grid;
  place-items: center;
  color: var(--calendar-weekday-text);
  font-size: min(18px, 2.1cqw);
  font-weight: 800;
  line-height: 1;
}

.dashboard-home__calendar-weekday.is-saturday {
  color: var(--calendar-weekend-blue);
}

.dashboard-home__calendar-weekday.is-sunday {
  color: var(--calendar-weekend-red);
}

.dashboard-home__calendar-day {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  gap: min(8px, 0.92cqw);
  padding: min(7px, 1.5cqw) min(2px, 0.43cqw) 0;
  box-sizing: border-box;
  overflow: hidden;
  border-style: solid;
  border-width: var(--calendar-day-border-width);
  border-color: var(--calendar-day-border);
  border-radius: min(7px, 1.5cqw);
  background: var(--calendar-day-bg);
  box-shadow: var(--calendar-day-shadow) !important;
  line-height: 1;
  contain: layout style;
}

.dashboard-home__calendar-day.is-today {
  z-index: 1;
  align-items: center;
  border: 1px solid var(--calendar-today-day-border);
  border-radius: min(7px, 1.5cqw);
  background: var(--calendar-today-day-bg);
  box-shadow: var(--calendar-today-day-shadow) !important;
  color: var(--calendar-today-text);
}

.dashboard-home__calendar-day.is-empty {
  opacity: 1;
}

.dashboard-home__calendar-solar {
  width: 100%;
  color: var(--calendar-solar-text);
  font-family: Georgia, "Times New Roman", serif;
  font-size: min(31px, 3.7cqw);
  font-weight: 500;
  line-height: 1.05;
  text-align: center;
}

.dashboard-home__calendar-lunar {
  display: block;
  width: 100%;
  max-width: 100%;
  overflow: hidden;
  color: var(--calendar-muted-text);
  font-size: min(15px, 1.9cqw);
  line-height: 1.24;
  letter-spacing: 0;
  text-align: center;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.dashboard-home__calendar-lunar-month,
.dashboard-home__calendar-lunar-day {
  display: inline;
}

@container (max-width: 520px) {
  .dashboard-home__calendar-lunar {
    line-height: 1.08;
    white-space: normal;
  }

  .dashboard-home__calendar-lunar-month,
  .dashboard-home__calendar-lunar-day {
    display: block;
    width: 100%;
  }
}

.dashboard-home__calendar-day.is-today .dashboard-home__calendar-lunar {
  color: var(--calendar-today-text);
  text-align: center;
}

.dashboard-home__calendar-day.is-today .dashboard-home__calendar-solar {
  color: var(--calendar-today-text);
  text-align: center;
}

.dashboard-home__calendar-day.is-saturday:not(.is-today) .dashboard-home__calendar-solar {
  color: var(--calendar-weekend-blue);
}

.dashboard-home__calendar-day.is-sunday:not(.is-today) .dashboard-home__calendar-solar {
  color: var(--calendar-weekend-red);
}
