  width: 100%;
  height: 100%;
  min-width: 0;
  min-height: 0;
  color: var(--countdown-title-color);
}

.dashboard-home__countdown-primary,
.dashboard-home__countdown-secondary,
.dashboard-home__countdown-footer {
  min-width: 0;
  min-height: 0;
  border: 1px solid var(--countdown-panel-border);
  background: var(--countdown-panel-bg);
  box-shadow: var(--countdown-glass-shadow);
}

.dashboard-home__countdown-primary {
