}

.dashboard-home__countdown-tile-top strong { color: var(--countdown-title-color) !important; font-size: 2.3cqw; }
.dashboard-home__countdown-tile-top small { color: var(--countdown-tile-muted-color) !important; font-size: 1.55cqw; }

.dashboard-home__countdown-tile-days {
  display: flex;
  align-items: baseline;
  justify-content: center;
