  flex: 0 0 48px;
  width: 48px;
  height: 48px;
}

.dashboard-home__plugin-launcher-menu {
  position: absolute;
  left: 50%;
  right: auto;
  bottom: calc(100% + 8px);
  transform: translateX(-50%);
  z-index: 4;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  width: 62px;
  padding: 6px;
  visibility: hidden;
  opacity: 0;
  pointer-events: none;
  border-style: solid;
  border-width: 1px 1px 0.5px;
  border-color: rgba(195, 212, 235, 0.3);
  border-radius: 8px !important;
