  transition: opacity 120ms ease;
}

.dashboard-home__plugin-launcher-menu::after {
  content: "";
  position: absolute;
  right: 0;
  bottom: -8px;
  left: 0;
  height: 8px;
}

.dashboard-home__scroll-toolbar:not(.is-popup-click) .dashboard-home__plugin-launcher:is(:hover, :focus-within) .dashboard-home__plugin-launcher-menu,
.dashboard-home__plugin-launcher.is-menu-open .dashboard-home__plugin-launcher-menu {
  visibility: visible;
  opacity: 1;
  pointer-events: auto;
}

/* 移动端工具栏保持在视图下方，并为 Obsidian 自带移动底栏预留一档高度。
   优先读取宿主提供的移动导航栏变量；宿主未提供时使用 48px 兜底。 */
@media (max-width: 760px) {
  .dashboard-home {
    --dashboard-mobile-native-toolbar-clearance: var(--mobile-navbar-height, var(--mobile-toolbar-height, 48px));
    --dashboard-scroll-toolbar-clearance: calc(var(--dashboard-mobile-native-toolbar-clearance) + 58px);
  }

  .dashboard-home .dashboard-home__scroll-toolbar {
    --dashboard-mobile-scroll-button-size: 34px;
    top: auto;
    right: 4px;
    bottom: calc(env(safe-area-inset-bottom, 0px) + var(--dashboard-mobile-native-toolbar-clearance) + 8px);
    left: 4px;
    width: max-content;
    max-width: calc(100% - 8px);
    margin-inline: auto;
    gap: 4px;
    padding: 4px;
    overflow: visible;
    justify-content: center;
    transform: none !important;
  }

  .dashboard-home .dashboard-home__scroll-toolbar.is-auto-hidden {
    transform: translateY(calc(100% - 6px)) !important;
  }

  .dashboard-home .dashboard-home__scroll-toolbar-button,
  .dashboard-home .dashboard-home__theme-launcher,
  .dashboard-home .dashboard-home__plugin-launcher {
    box-sizing: border-box;
    width: var(--dashboard-mobile-scroll-button-size) !important;
    min-width: var(--dashboard-mobile-scroll-button-size) !important;
    max-width: var(--dashboard-mobile-scroll-button-size) !important;
    height: var(--dashboard-mobile-scroll-button-size) !important;
    min-height: var(--dashboard-mobile-scroll-button-size) !important;
    max-height: var(--dashboard-mobile-scroll-button-size) !important;
    flex-basis: var(--dashboard-mobile-scroll-button-size) !important;
    aspect-ratio: 1 / 1;
  }

  .dashboard-home .dashboard-home__scroll-toolbar-button {
    padding: calc(var(--dashboard-mobile-scroll-button-size) / 12);
    border-radius: calc(var(--dashboard-mobile-scroll-button-size) / 6) !important;
  }

  .dashboard-home .dashboard-home__scroll-toolbar-section-combined {
    display: none;
  }

  .dashboard-home .dashboard-home__scroll-toolbar-section-mobile {
    display: inline-flex;
  }

  .dashboard-home .dashboard-home__scroll-toolbar-icon {
    font-size: calc(var(--dashboard-mobile-scroll-button-size) / 3);
  }

  .dashboard-home .dashboard-home__scroll-toolbar-label {
    margin-top: calc(var(--dashboard-mobile-scroll-button-size) / 24);
    font-size: calc(var(--dashboard-mobile-scroll-button-size) * 0.1875);
  }

  .dashboard-home--skin-island .dashboard-home__scroll-toolbar-button::after {
    inset: calc(var(--dashboard-mobile-scroll-button-size) / 16);
    border-radius: calc(var(--dashboard-mobile-scroll-button-size) / 6) !important;
  }

  .dashboard-home .dashboard-home__theme-launcher-menu {
    top: auto;
    right: auto;
    bottom: calc(100% + 8px);
    left: 0;
    transform: none;
  }

  .dashboard-home .dashboard-home__plugin-launcher-menu {
    top: auto;
    right: 0;
    bottom: calc(100% + 8px);
    left: auto;
    transform: none;
  }

  .dashboard-home .dashboard-home__theme-launcher-menu::after,
  .dashboard-home .dashboard-home__plugin-launcher-menu::after {
    top: auto;
    right: 0;
    bottom: -8px;
    left: 0;
    height: 8px;
  }

  .dashboard-home .dashboard-home__theme-launcher:is(:hover, :focus-within):not(.is-mobile-open) .dashboard-home__theme-launcher-menu,
  .dashboard-home .dashboard-home__plugin-launcher:is(:hover, :focus-within):not(.is-mobile-open) .dashboard-home__plugin-launcher-menu {
    visibility: hidden;
    opacity: 0;
    pointer-events: none;
  }

  .dashboard-home .dashboard-home__theme-launcher.is-mobile-open .dashboard-home__theme-launcher-menu,
  .dashboard-home .dashboard-home__plugin-launcher.is-mobile-open .dashboard-home__plugin-launcher-menu {
    visibility: visible;
    opacity: 1;
    pointer-events: auto;
  }
}

