  max-width: 100%;
  min-width: 0;
  min-height: 19px;
  gap: 4px;
  overflow: hidden;
}

.dashboard-home__progress-item-actions > b {
  max-width: 100%;
  margin-left: 0;
  overflow-wrap: normal;
  text-align: right;
  white-space: nowrap;
}

.dashboard-home__progress-item-buttons {
  display: flex;
  flex: 0 0 0;
  justify-content: flex-end;
  align-items: center;
  gap: 4px;
  width: 0;
  min-width: 0;
  max-width: 0;
  opacity: 0;
  visibility: hidden;
  overflow: hidden;
  transform: none;
  pointer-events: none;
  transition:
    flex-basis 120ms ease 0ms,
    width 120ms ease 0ms,
    max-width 120ms ease 0ms,
    opacity 120ms ease 0ms,
    visibility 0s linear 120ms;
  contain: layout style;
}

.dashboard-home__progress-item-buttons:empty {
  display: none;
}

.dashboard-home__progress-card-item:is(:hover, :focus-within) .dashboard-home__progress-item-buttons {
  flex-basis: 64px;
  width: 64px;
  max-width: 64px;
  opacity: 1;
  visibility: visible;
  transform: none;
  pointer-events: auto;
  transition:
    flex-basis 120ms ease 300ms,
    width 120ms ease 300ms,
    max-width 120ms ease 300ms,
    opacity 120ms ease 300ms,
    visibility 0s linear 300ms;
}

.dashboard-home__progress-item-actions > b {
  flex: 0 0 auto;
  color: #2f6fae;
  font-size: 17px;
  font-weight: 900;
}

.dashboard-home__progress-adjust {
  appearance: none;
  display: grid;
  place-items: center;
  box-sizing: border-box;
  flex: 1 1 30px;
  width: 30px;
  min-width: 0;
  max-width: 30px;
  height: 30px;
  padding: 0;
  border-style: solid;
  border-width: 1px 1px 0.5px;
  border-color: rgba(188, 208, 234, 0.22) !important;
  border-radius: var(--dashboard-node-radius);
  outline: none;
  background: linear-gradient(180deg, rgba(247, 250, 255, 0.98), rgba(232, 240, 252, 0.94)) !important;
  box-shadow:
    inset 0 0 0 2px rgba(255, 255, 255, 0.76),
    0 -1px 0 0 rgba(167, 194, 226, 0.24) !important;
  color: #315f8f;
  font-size: 19px;
  font-weight: 800;
  line-height: 1;
}

.dashboard-home__progress-adjust:disabled {
  cursor: default;
  opacity: 0.34;
}

.dashboard-home__progress-line {
  display: flex;
  align-items: center;
  width: 100%;
  min-width: 0;
  gap: 4px;
}

.dashboard-home__progress-track {
  position: relative;
  flex: 1 1 auto;
  width: auto;
  min-width: 0;
  height: 8px;
  border: 1px solid var(--planning-glass-border);
  border-radius: 999px;
  background: rgba(217, 228, 242, 0.55);
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.64);
  overflow: hidden;
  contain: layout paint style;
}

.dashboard-home__progress-track.is-profit::after {
  content: "";
  position: absolute;
  top: 1px;
  bottom: 1px;
  left: calc(50% - 0.5px);
  width: 1px;
  background: rgba(109, 133, 162, 0.34);
  pointer-events: none;
}

.dashboard-home__progress-fill {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  width: 0;
  border-radius: inherit;
}

.dashboard-home__progress-fill.is-positive {
  border-radius: 0 999px 999px 0;
}

.dashboard-home__progress-fill.is-negative {
  border-radius: 999px 0 0 999px;
}

.dashboard-home__progress-fill.is-neutral {
  width: 0 !important;
}

.dashboard-home__progress-meta {
  margin-top: 4px;
}

.dashboard-home__progress-note {
  margin-top: 5px;
  color: #5f7790;
  font-size: 11px;
  line-height: 1.45;
  white-space: pre-wrap;
  word-break: break-word;
}

.dashboard-home__progress-empty {
  display: grid;
  place-items: center;
  min-height: 52px;
  color: var(--text-muted);
  font-size: 11px;
}
