}

.dashboard-home__tutorial-svg {
  display: block;
  width: 100%;
  height: auto;
}

.tutorial-svg__shell {
  fill: var(--background-primary);
  stroke: var(--background-modifier-border);
  stroke-width: 2;
}

.tutorial-svg__banner {
  fill: #dff4ff;
  stroke: #91b9d2;
  stroke-width: 2;
}

.tutorial-svg__card {
  stroke: var(--background-modifier-border);
  stroke-width: 2;
}

.tutorial-svg__card--1 { fill: #fff9e8; }
.tutorial-svg__card--2 { fill: #e5f1bd; }
.tutorial-svg__card--3 { fill: #f7e8ed; }
.tutorial-svg__icon { fill: #70bd8e; }
.tutorial-svg__line {
  stroke: #6f7f8d;
