.dashboard-home__welcome-overlay {
  position: fixed;
  inset: 0;
  z-index: 180;
  display: grid;
  place-items: center;
  box-sizing: border-box;
  padding: 24px;
  background: rgba(24, 39, 58, 0.32);
  opacity: 1;
  transition: opacity 900ms ease;
}

.dashboard-home__welcome-overlay.is-closing {
  opacity: 0;
  pointer-events: none;
}

.dashboard-home__welcome-overlay.is-entering {
  opacity: 0;
}

.dashboard-home__welcome-panel {
  display: grid;
  place-items: center;
  align-content: center;
  width: min(calc(100vw - 48px), calc((100vh - 64px) * 1.7778), 1180px);
  aspect-ratio: 16 / 9;
  min-width: 0;
  min-height: 0;
  box-sizing: border-box;
  padding: clamp(28px, 5vw, 72px);
  border: 1px solid rgba(195, 212, 235, 0.34);
  border-radius: var(--dashboard-node-radius);
  background:
    linear-gradient(155deg, rgba(255, 255, 255, 0.98), rgba(232, 241, 253, 0.96));
  box-shadow:
    inset 0 0 0 2px rgba(255, 255, 255, 0.76),
    0 -1px 0 0 rgba(167, 194, 226, 0.24);
  color: #203040;
  transition:opacity 900ms ease;
}

.dashboard-home__welcome-overlay.is-closing .dashboard-home__welcome-panel {
  opacity: 0;
}

.dashboard-home__welcome-overlay.is-entering .dashboard-home__welcome-panel {
  opacity: 0;
}

.dashboard-home__welcome-message {
  display:flex;
  align-items:center;
  justify-content:center;
  box-sizing:border-box;
  width:82%;
  height:48%;
  max-width:82%;
  max-height:56%;
  color: inherit;
  font-size:clamp(96px,14vw,240px);
  font-weight: 900;
  line-height:1.16;
  text-align: center;
  overflow-wrap: anywhere;
  word-break:break-word;
  overflow:hidden;
}

.dashboard-home__welcome-message-text {
  display:block;
  width:100%;
  max-width:100%;
  min-width:0;
  color:inherit;
  font:inherit;
  line-height:inherit;
  text-align:inherit;
  white-space:normal;
  overflow-wrap:anywhere;
  word-break:break-word;
}

.dashboard-home__welcome-overlay.is-dark {
  background: rgba(4, 10, 18, 0.68);
}

.dashboard-home__welcome-overlay.is-dark .dashboard-home__welcome-panel {
  position:relative;
  isolation:isolate;
  overflow:hidden;
  border:2px solid #58789a;
  border-radius:var(--dashboard-node-radius)!important;
  background:#17283d;
  box-shadow:
    inset 0 0 0 2px rgba(173,205,237,.12),
    0 -1px 0 0 rgba(93, 128, 168, 0.32);
  color: #e8f2ff;
  clip-path:none!important;
}

.dashboard-home__welcome-overlay.is-light {
  background:rgba(37,64,92,.38);
}

.dashboard-home__welcome-overlay.is-light .dashboard-home__welcome-panel {
  position:relative;
  isolation:isolate;
  overflow:hidden;
  border:2px solid #8bb7e4;
  border-radius:var(--dashboard-node-radius)!important;
  background:#e8f4ff;
  box-shadow:
    inset 0 0 0 2px rgba(255,255,255,.82),
    0 -1px 0 0 rgba(94,140,190,.28);
  color:#244766;
  clip-path:none!important;
}

.dashboard-home__welcome-overlay.is-light .dashboard-home__welcome-panel::before,
.dashboard-home__welcome-overlay.is-dark .dashboard-home__welcome-panel::before {
  content:"";
  position:absolute;
  top:clamp(42px,9%,76px);
  left:50%;
  z-index:-1;
  width:clamp(48px,6vw,76px);
  aspect-ratio:1;
  border-radius:50%;
  transform:translateX(-50%);
}

.dashboard-home__welcome-overlay.is-light .dashboard-home__welcome-panel::before {
  border:2px solid rgba(76,133,191,.32);
  background:#ffd86f;
  box-shadow:inset 0 0 0 5px rgba(255,255,255,.48);
}

.dashboard-home__welcome-overlay.is-dark .dashboard-home__welcome-panel::before {
  border:2px solid rgba(166,198,230,.38);
  background:#dce8f5;
  box-shadow:inset 0 0 0 5px rgba(255,255,255,.16);
}

.dashboard-home__welcome-overlay.is-light .dashboard-home__welcome-panel::after,
.dashboard-home__welcome-overlay.is-dark .dashboard-home__welcome-panel::after {
  content:"";
  position:absolute;
  right:-8%;
  bottom:-16%;
  left:-8%;
  z-index:-1;
  height:38%;
  border-radius:50% 50% 0 0 / 68% 68% 0 0;
}

.dashboard-home__welcome-overlay.is-light .dashboard-home__welcome-panel::after {
  border-top:2px solid rgba(91,145,199,.24);
  background:#cfe6f7;
}

.dashboard-home__welcome-overlay.is-dark .dashboard-home__welcome-panel::after {
  border-top:2px solid rgba(119,151,188,.28);
  background:#203b57;
}

.dashboard-home__welcome-overlay.is-light .dashboard-home__welcome-message,
.dashboard-home__welcome-overlay.is-dark .dashboard-home__welcome-message {
  position:relative;
  z-index:1;
  box-sizing:border-box;
  width:82%;
  height:48%;
  max-width:82%;
  padding:clamp(20px,3vw,40px) clamp(28px,5vw,72px);
  border-radius:var(--dashboard-node-radius)!important;
  clip-path:none!important;
  overflow:hidden!important;
}

.dashboard-home__welcome-overlay.is-light .dashboard-home__welcome-message {
  border:1px solid #9fc2e6;
  background:#fbfdff;
  box-shadow:
    inset 0 0 0 3px rgba(255,255,255,.82),
    0 -1px 0 0 rgba(94,140,190,.22);
  color:#244766;
  text-shadow:0 1px 0 rgba(255,255,255,.9);
}

.dashboard-home__welcome-overlay.is-dark .dashboard-home__welcome-message {
  border:1px solid #58789a;
  background:#1f344c;
  box-shadow:
    inset 0 0 0 3px rgba(173,205,237,.08),
    0 -1px 0 0 rgba(5,12,22,.46);
  color:#eef6ff;
  text-shadow:0 1px 0 rgba(4,10,18,.72);
}

.dashboard-home__welcome-overlay.is-island {
