  color: #5a3824;
  clip-path:none!important;
}

.dashboard-home__welcome-overlay.is-island .dashboard-home__welcome-panel::before {
  content:"";
  position:absolute;
  top:clamp(42px,9%,76px);
  left:50%;
  z-index:-1;
  width:clamp(48px,6vw,76px);
  aspect-ratio:1;
  border:2px solid rgba(171,112,42,.34);
  border-radius:50%;
  background:#f3c75f;
  box-shadow:inset 0 0 0 5px rgba(255,253,242,.5);
  transform:translateX(-50%);
}

.dashboard-home__welcome-overlay.is-island .dashboard-home__welcome-panel::after {
  content:"";
  position:absolute;
  right:-8%;
  bottom:-16%;
  left:-8%;
