  border-top:2px solid rgba(82,126,76,.24);
  border-radius:50% 50% 0 0 / 68% 68% 0 0;
  background:#b8d9aa;
}

.dashboard-home__welcome-overlay.is-island .dashboard-home__welcome-message {
