/* Unified planner: day, week, month and year views. */
.dashboard-home__planner-content { display:flex; min-height:0; flex:1; flex-direction:column; gap:8px; padding:8px; }
.dashboard-home__planner-content.is-tasks { overflow:auto; }
.dashboard-home__planner-all-tasks { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); align-items:start; gap:8px; min-width:0; }
.dashboard-home__planner-all-source { display:flex; min-width:0; min-height:100%; flex-direction:column; gap:7px; padding:7px; border:1px solid rgba(195,212,235,.3); border-radius:var(--dashboard-node-radius); background:var(--planning-glass-panel); }
.dashboard-home__planner-all-source-title { padding:8px 10px; border:1px solid rgba(79,142,232,.26); border-radius:var(--dashboard-node-radius); background:rgba(79,142,232,.14); color:#24547b; font-size:12px; font-weight:900; text-align:center; }
.dashboard-home__planner-all-group { overflow:hidden; border:1px solid rgba(195,212,235,.24); border-radius:var(--dashboard-node-radius); background:rgba(255,255,255,.38); }
.dashboard-home__planner-all-group-title { padding:6px 9px; border-bottom:1px solid rgba(79,142,232,.2); color:#24547b; background:rgba(79,142,232,.1); font-size:10px; font-weight:900; text-align:center; }
.dashboard-home__planner-view-toolbar {
  flex:0 0 auto;
  margin:0;
  padding:8px;
  border-style:solid;
  border-width:1px 1px .5px;
  border-color:rgba(195,212,235,.24);
  border-radius:var(--dashboard-node-radius);
  background:linear-gradient(180deg,rgba(255,255,255,.96),rgba(244,248,255,.9));
  box-shadow:inset 0 0 0 2px rgba(255,255,255,.76),0 -1px 0 0 rgba(167,194,226,.24);
