.dashboard-home__planner-range-title { padding:7px 10px; border:1px solid rgba(195,212,235,.24); border-radius:var(--dashboard-node-radius); background:var(--planning-glass-panel); color:var(--dashboard-text); font-size:13px; font-weight:900; text-align:center; }
.dashboard-home__planner-content.is-day { overflow:hidden; }
.dashboard-home__planner-day-range,.dashboard-home__planner-week-range,.dashboard-home__planner-font-size-range { display:none; grid-template-columns:auto minmax(180px,1fr); align-items:center; gap:10px; padding:8px 10px; border:1px solid rgba(195,212,235,.24); border-radius:var(--dashboard-node-radius); background:var(--planning-glass-panel); }
.dashboard-home__planner-day-range.is-open,.dashboard-home__planner-week-range.is-open,.dashboard-home__planner-font-size-range.is-open { display:grid; }
.dashboard-home__planner-day-range-value,.dashboard-home__planner-week-range-value,.dashboard-home__planner-font-size-range-value { min-width:92px; color:var(--dashboard-text); font-size:11px; font-weight:800; }
