.dashboard-home__planner-day-timeline { display:flex; min-height:0; flex:1; flex-direction:column; gap:8px; border-radius:var(--dashboard-node-radius)!important; overflow-y:auto; padding-right:2px; }
.dashboard-home__planner-day-lane { display:grid; grid-template-columns:90px minmax(0,1fr); min-height:54px; border:1px solid rgba(195,212,235,.24); border-radius:var(--dashboard-node-radius); background:var(--planning-glass-panel); overflow:hidden; }
