/* 第四分区：左侧分组索引 + 右侧六级递归任务工作区 */
.dashboard-home__checkins-workspace {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  grid-template-rows: auto minmax(0, 1fr);
  gap: 12px;
  margin-top: 8px;
  min-height: 420px;
  flex: 1 1 auto;
  align-self: stretch;
}

.dashboard-home__checkins-groups,
.dashboard-home__checkins-content {
  min-width: 0;
  border: 1px solid var(--background-modifier-border);
  border-radius: 14px;
  background: var(--background-secondary);
  overflow: hidden;
}

.dashboard-home__checkins-groups { padding: 10px; }
.dashboard-home__checkins-content { padding: 10px; }
.dashboard-home__checkins-content {
  display: flex;
  flex-direction: column;
  align-self: stretch;
  min-height: 0;
  height: 100%;
}
.dashboard-home__checkins-pane-title,
.dashboard-home__checkins-content-header,
.dashboard-home__checkins-level-header {
  border-radius: 10px;
}
.dashboard-home__checkins-pane-title {
  padding: 9px 10px;
  text-align: center;
  font-weight: 700;
  background: var(--background-primary-alt);
}
.dashboard-home__checkins-group-list {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 8px;
  min-width: 0;
}
.dashboard-home__checkins-pane-title--with-actions {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
}
.dashboard-home__checkins-pane-actions { display: flex; align-items: center; gap: 6px; }
.dashboard-home__checkins-pane-action {
  min-height: 34px;
  padding: 5px 10px;
  border-radius: 8px !important;
  background: var(--background-primary);
  color: var(--text-normal);
}
.dashboard-home__checkins-pane-action.is-delete { color: var(--text-error); }
.dashboard-home__checkins-category-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));
  align-items: start;
  gap: 10px;
  margin-top: 10px;
}
.dashboard-home__checkins-category-column.is-collapsed > .dashboard-home__checkins-group-list { display: none; }
.dashboard-home__checkins-category-action-spacer { width: 40px; min-width: 40px; }
.dashboard-home__checkins-category-column {
  min-width: 0;
  padding: 8px;
  border: 1px solid var(--background-modifier-border);
  border-radius: 12px;
  background: var(--background-secondary);
}
.dashboard-home__checkins-category-column.is-active {
  border-color: var(--interactive-accent);
  box-shadow: inset 0 0 0 1px var(--interactive-accent);
}
.dashboard-home__checkins-category-header {
  display: grid;
  grid-template-columns: 40px minmax(0, 1fr) 40px;
  align-items: stretch;
  gap: 7px;
  margin-bottom: 8px;
}
.dashboard-home__checkins-category-action {
  width: 40px;
  min-width: 40px;
  height: 40px;
  min-height: 40px;
  padding: 3px;
  display: inline-flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
