/* Fourth-section vertical tree: dynamic hierarchy connectors and consistent content centering. */
.dashboard-home__checkins-content.is-vertical-mode {
  --checkins-tree-indent-step: 18px;
  --checkins-tree-line: rgba(93, 128, 166, 0.3);
  --checkins-tree-line-active: rgba(62, 119, 190, 0.82);
}

.dashboard-home__checkins-content.is-vertical-mode
  .dashboard-home__checkins-level-item.is-vertical-tree-node {
  position: relative;
  z-index: 2;
  overflow: visible !important;
  isolation: isolate;
  line-height: 1.3;
}

.dashboard-home__checkins-content.is-vertical-mode
  .dashboard-home__checkins-level-item.is-vertical-tree-node
  > :not(.dashboard-home__tree-connectors) {
  position: relative;
  z-index: 2;
}

.dashboard-home__checkins-content.is-vertical-mode
  .dashboard-home__checkins-level-item.is-vertical-tree-node
  > .dashboard-home__leaf-body {
  transform: translateY(1.5px);
}

.dashboard-home__tree-connector-layer {
  position: absolute;
  z-index: 1;
  inset: 0 auto auto 0;
  overflow: visible;
  pointer-events: none;
}

.dashboard-home__tree-connector-rail,
.dashboard-home__tree-connector-edge {
  fill: none;
  stroke-width: 2px;
  stroke-linecap: round;
  stroke-linejoin: round;
  vector-effect: non-scaling-stroke;
  shape-rendering: geometricPrecision;
}

.dashboard-home__tree-connector-rail {
  stroke: var(--checkins-tree-line);
}

.dashboard-home__tree-connector-edge {
  stroke: transparent;
  transition: stroke 120ms ease;
}

.dashboard-home__tree-connector-edge.is-hierarchy-edge-active {
  stroke: var(--checkins-tree-line-active);
}

.dashboard-home.dashboard-home--resolved-dark.dashboard-home--skin-default
  .dashboard-home__checkins-content.is-vertical-mode {
  --checkins-tree-line: rgba(145, 184, 255, 0.3);
  --checkins-tree-line-active: rgba(145, 184, 255, 0.92);
}

.dashboard-home.dashboard-home--skin-island
  .dashboard-home__checkins-content.is-vertical-mode {
  --checkins-tree-line: rgba(112, 143, 91, 0.34);
  --checkins-tree-line-active: rgba(77, 150, 98, 0.9);
}

/* Cancelled tasks in island mode must use an island surface, never the light glass fallback. */
.dashboard-home.dashboard-home--skin-island
  .dashboard-home__card[data-section="checkins"]
  .dashboard-home__checkins-level-item.is-cancelled {
  border-color: rgba(161, 112, 81, 0.58) !important;
  background: #e8d7b2 !important;
  box-shadow: none !important;
  color: #76513d !important;
}

/* Keep the mobile planner toolbar fluid after the late desktop planner grid baseline. */
@media (max-width: 760px) {
  .dashboard-home .dashboard-home__card[data-section="events"] > .dashboard-home__planner-toolbar {
    display: flex !important;
    flex-wrap: wrap;
    align-items: flex-start;
    align-content: flex-start;
    row-gap: 8px;
  }
}

/* Mobile has no stable hover/focus reveal: keep non-Banner action icons visible and tappable. */
@media (max-width: 760px) {
  .dashboard-home :is(
    .dashboard-home__shared-module-settings,
    .dashboard-home__task-icon-actions,
    .dashboard-home__collapse-controls,
    .dashboard-home__pomodoro-manager-trigger,
    .dashboard-home__pomodoro-compact-actions,
    .dashboard-home__schedule-period-reset,
    .dashboard-home__progress-item-buttons,
    .dashboard-home__checkins-category-action
  ) {
    opacity: 1 !important;
    visibility: visible !important;
    pointer-events: auto !important;
  }

  /* 目录、画板和第一分区的分组操作栏不能继续沿用桌面端绝对定位。
     固定显示后改为真实三列布局，视觉位置和触摸命中盒始终一致。 */
  .dashboard-home :is(
    .dashboard-home__nav-group-header,
    .dashboard-home__board-a-column > .dashboard-home__section-row,
    .dashboard-home__board-a-panel-title--active
  ) {
    display: grid !important;
    grid-template-columns: max-content minmax(0, 1fr) max-content;
    align-items: center !important;
    column-gap: 5px;
    height: auto;
    min-height: 42px;
    padding: 4px !important;
    overflow: visible !important;
  }

  .dashboard-home :is(
    .dashboard-home__nav-group-header,
    .dashboard-home__board-a-column > .dashboard-home__section-row
  ) > .dashboard-home__nav-group-title-wrap,
  .dashboard-home .dashboard-home__board-a-panel-title--active > .dashboard-home__collapse-label {
    grid-column: 2;
    grid-row: 1;
    width: 100%;
    min-width: 0;
    max-width: none;
    margin: 0;
  }

  .dashboard-home :is(
    .dashboard-home__nav-group-header,
    .dashboard-home__board-a-column > .dashboard-home__section-row,
    .dashboard-home__board-a-panel-title--active
  ) > .dashboard-home__task-icon-actions--header-left {
    position: static !important;
    grid-column: 1;
    grid-row: 1;
    justify-self: start;
    margin: 0;
    transform: none !important;
  }

  .dashboard-home :is(
    .dashboard-home__nav-group-header,
    .dashboard-home__board-a-column > .dashboard-home__section-row,
    .dashboard-home__board-a-panel-title--active
  ) > .dashboard-home__task-icon-actions--header-right {
    position: static !important;
    grid-column: 3;
    grid-row: 1;
    justify-self: end;
    margin: 0;
    transform: none !important;
  }

  .dashboard-home .dashboard-home__task-icon-actions--rail > :is(button, .dashboard-home__icon-button) {
    position: relative;
    z-index: 2;
    box-sizing: border-box;
    flex: 0 0 auto;
    touch-action: manipulation;
    transform: none !important;
    transition: none !important;
    -webkit-tap-highlight-color: transparent;
  }

  .dashboard-home .dashboard-home__task-icon-actions--rail > :is(button, .dashboard-home__icon-button) > * {
    pointer-events: none;
  }

  .dashboard-home .dashboard-home__progress-item-buttons:not(:empty) {
    flex-basis: 64px !important;
    width: 64px !important;
    max-width: 64px !important;
    overflow: visible !important;
  }

  .dashboard-home :is(
    .dashboard-home__pomodoro-compact-actions,
    .dashboard-home__schedule-period-reset
  ) {
    transform: none !important;
  }

  .dashboard-home :is(
    .dashboard-home__matrix-group-actions,
    .dashboard-home__matrix-label-actions
  ) {
    opacity: 1 !important;
    pointer-events: auto !important;
    max-height: 40px !important;
    padding: 4px !important;
    margin-bottom: 4px !important;
    overflow: visible !important;
  }

  .dashboard-home .dashboard-home__matrix-group-actions {
    border-top-width: 1px !important;
  }
}
